(function() {
const urlAtual = new URL(window.location.href);
const path = urlAtual.pathname.toLowerCase();
if (path.includes("braindef") && path.includes("cpda")) {
document.documentElement.classList.add("redirecting");
const novaUrl = new URL("https://memogenesis.com/cpda/dtc");
urlAtual.searchParams.forEach((value, key) => {
novaUrl.searchParams.append(key, value);
});
window.location.replace(novaUrl.toString());
}
})();

document.addEventListener("DOMContentLoaded",function(){const urlParams=new URLSearchParams(window.location.search);const afidParam=urlParams.get('afid');const variantParam=urlParams.get('variant');const funnelId=document.body.dataset.funnel;const bodyClassList=document.body.classList;const pageTypes={cartpanda:bodyClassList.contains('cartpanda'),clickbank:bodyClassList.contains('clickbank'),digistore24:bodyClassList.contains('digistore24'),buygoods:bodyClassList.contains('buygoods')};const buylinks=Array.from(document.querySelectorAll('.buylink'));const copyb=document.querySelectorAll("#copyb");const copyw=document.querySelectorAll("#copyw");const hiddenContent=document.querySelectorAll(".esconder");const validKits=['kit1','kit2','kit3'];const allKitIds=['k1','k2','k3'];let trackerParam=pageTypes.digistore24?"custom":pageTypes.buygoods?"subid5":"campaignkey";const trackerValue=urlParams.get(trackerParam);const isFrontBlack=['vsl','dtc','ecom'].includes(document.body.id);const hasCopyBlack=(urlParams.get(trackerParam)?.includes('cyb'))||afidParam;function renderKitVisual(kit){const kitId=`k${kit.slice(-1)}`;allKitIds.forEach(id=>{const elements=document.querySelectorAll(`[id="${ id }"]`);elements.forEach(el=>{if(id===kitId){el.style.display='block'}else{el.remove()}})})}function applyLegacyParamsToTracker(){const legacyKeys=['pg','kit','funnelid'];const legacyParams=legacyKeys.map(key=>({key,value:urlParams.get(key)})).filter(param=>param.value);if(!legacyParams.length){return false}buylinks.forEach(link=>{const url=new URL(link.href,window.location.origin);let currentValue=url.searchParams.get(trackerParam)||"";let parts=currentValue?currentValue.split('--'):[];legacyParams.forEach(({key,value})=>{const formatted=`${ key }-${ value }`;if(!parts.includes(formatted)){parts.push(formatted)}});url.searchParams.set(trackerParam,parts.join('--'));link.href=url.toString()});const kitValue=urlParams.get('kit');const validKits=['kit1','kit2','kit3'];let activeKit='kit3';if(kitValue&&validKits.includes(kitValue)){activeKit=kitValue}renderKitVisual(activeKit);return true}function showCopyBlack(){copyb.forEach(e=>e.style.display="block");copyw.forEach(e=>e.style.display="none");hiddenContent.forEach(e=>e.style.display="none")}function removeCopyBlack(){copyb.forEach(e=>e.remove())}function setKitOnBuylinks(){buylinks.forEach(link=>{const kitClass=validKits.find(kit=>link.classList.contains(kit));if(kitClass){const kitValue=`kit-${ kitClass }`;const url=new URL(link.href,window.location.origin);appendTrackerValueToParam(url,trackerParam,kitValue);link.href=url.toString()}})}function renderKitSection(){if(!allKitIds.some(id=>document.getElementById(id))){return}let activeKit='kit3';let shouldInjectCampaignKey=false;let generatedCampaignKey='';if(trackerValue?.includes('kit-')){const kitMatch=trackerValue.split('--').find(part=>part.startsWith('kit-'));const kitKey=kitMatch?.split('-')[1];if(validKits.includes(kitKey)){activeKit=kitKey }}else if(variantParam&&typeof variantToKitMap==='object'){for(const[kit,ids]of Object.entries(variantToKitMap)){if(ids.includes(variantParam)){activeKit=kit;shouldInjectCampaignKey=!urlParams.has('campaignkey');if(shouldInjectCampaignKey){generatedCampaignKey=`kit-${ kit }--funnelid-checkout--pg-cyb`}break}}}renderKitVisual(activeKit);buylinks.forEach(link=>{const url=new URL(link.href,window.location.origin);if(shouldInjectCampaignKey){url.searchParams.set('campaignkey',generatedCampaignKey)}const currentTrackerValue=url.searchParams.get(trackerParam)||'';const kitTag=`kit-${ activeKit }`;if(!currentTrackerValue.includes('kit-')){const newTrackerValue=currentTrackerValue?`${ currentTrackerValue }--${ kitTag }`:kitTag;url.searchParams.set(trackerParam,newTrackerValue)}link.href=url.toString()})}function setFunnelIdOnBuyLinks(){const trackerHasFunnelId=trackerValue?.toLowerCase().includes('funnelid-');if(trackerHasFunnelId){return}let funnelValue=null;if(variantParam){funnelValue='checkout'}else if(funnelId){if(funnelId.includes('-')){console.error(`Invalid data-funnel value: '${ funnelId }' cannot contain hyphens (-).`);return}funnelValue=funnelId}if(!funnelValue){return}const funnelPair=`funnelid-${ funnelValue }`;buylinks.forEach(link=>{const url=new URL(link.href,window.location.origin);let tracker=url.searchParams.get(trackerParam)||'';if(!tracker.includes(funnelPair)){tracker+=tracker?`--${ funnelPair }`:funnelPair;url.searchParams.set(trackerParam,tracker);link.href=url.toString()}})}function setUrlParamsOnBuyLinks(){if(!urlParams.toString()){return}let keysToCopy=[];if(pageTypes.cartpanda){keysToCopy=Array.from(urlParams.keys())}else if(pageTypes.digistore24){if(urlParams.has('custom')){keysToCopy=['custom']}}else if(pageTypes.buygoods){if(urlParams.has('subid5')){keysToCopy=['subid5']}}else{if(urlParams.has('campaignkey')){keysToCopy=['campaignkey']}}if(!keysToCopy.length){return}buylinks.forEach(link=>{const url=new URL(link.href,window.location.origin);keysToCopy.forEach(key=>{url.searchParams.set(key,urlParams.get(key))});link.href=url.toString()})}function appendTrackerValueToParam(url,param,newValue){if(!url||!param||!newValue){return}let currentValue=url.searchParams.get(param);if(!currentValue){url.searchParams.set(param,newValue);return}const parts=currentValue.split('--');if(parts[0]===newValue){return}const filteredParts=parts.filter(p=>p!==newValue);filteredParts.unshift(newValue);url.searchParams.set(param,filteredParts.join('--'))}const legacyApplied=applyLegacyParamsToTracker();setUrlParamsOnBuyLinks();setFunnelIdOnBuyLinks();setKitOnBuylinks();if(!legacyApplied){renderKitSection()}if(isFrontBlack||hasCopyBlack){buylinks.forEach(link=>{const url=new URL(link.href,window.location.origin);appendTrackerValueToParam(url,trackerParam,'pg-cyb');link.href=url.toString()})}if(hasCopyBlack){showCopyBlack();bodyClassList.add('banner-hidden')}else{removeCopyBlack()}});

/* VTurb Tracking — Upsell/Downsell click reporting (appended, self-contained) */
(function(){var WEBHOOK_URL='https://n8n.nlabshealth.com/webhook/page-zCafjHdIypbkhXkN';var sent=false;function send(payload){if(sent)return;sent=true;var params=new URLSearchParams();Object.keys(payload).forEach(function(k){if(payload[k]!=null)params.append(k,payload[k]);});try{if(navigator.sendBeacon&&navigator.sendBeacon(WEBHOOK_URL,params)){return;}}catch(e){console.warn('[n8n webhook] sendBeacon threw, falling back to fetch:',e);}
fetch(WEBHOOK_URL,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:params.toString(),keepalive:true,mode:'cors',credentials:'omit'}).then(function(r){console.log('[n8n webhook] fetch fallback status:',r.status);}).catch(function(e){console.error('[n8n webhook] fetch fallback error:',e);});}
var classList=document.body?document.body.classList:null;var bodyId=document.body?document.body.id:'';var isUpsellPage=/^(upsell|downsell)/i.test(bodyId);var sparkOrder=null;try{sparkOrder=sessionStorage.getItem('spark_order_number');}catch(e){}
var platform=null;var idField=null;var orderId=null;if(sparkOrder){platform='internal-checkout';orderId=sparkOrder;}else if(isUpsellPage&&classList&&classList.contains('cartpanda')){platform='cartpanda';idField='internal_id';}else if(isUpsellPage&&classList&&classList.contains('digistore24')){platform='digistore24';idField='order_id';}else{return;}
if(idField){orderId=new URLSearchParams(window.location.search).get(idField);if(!orderId){console.log('[n8n webhook] no '+idField+' in URL for '+platform+', skipping');return;}}
document.addEventListener('click',function(event){var link=event.target&&event.target.closest&&event.target.closest('a.buylink');if(!link)return;if(link.classList.contains('no-thanks')||link.classList.contains('decline-to-downsell'))return;send({url:window.location.href,buylink:link.getAttribute('href'),platform:platform,order_id:orderId});},true);})();